            const closed = state();
            FW.setFoundryWindow("ftools", true);
            bar?.toggleExpanded?.(false);
            const narrowed = state();
            FW.setFoundryWindow("ftools", false);
            bar?.changeTab?.(bar.tabGroups?.primary ?? "chat", "primary");
            const byTab = state();
