        equal(J(["frisk", "rummage", "unseen", "plant"].map(part => listedTraits({ kind: "action", key: "palm", part }))),
            J([["body"], ["hand"], ["shadow"], []]), "[the statistic the ruling reads for Palm's frisk, rummage, unseen and plant]");
